:root{
  --cyan:#74e4ff;--gold:#ffcf5c;--red:#ff645e;--green:#7cf0b2;
  --ink:#040b11;--panel:rgba(5,17,24,.88);--line:rgba(116,228,255,.22);
  --soft:#9db4be;--white:#f2fbff;
}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{width:100%;height:100%;margin:0;overflow:hidden;background:#02070b;color:var(--white);
  font-family:"Trebuchet MS",Inter,system-ui,sans-serif;user-select:none;overscroll-behavior:none}
canvas{display:block}
button{font-family:inherit}
.hidden{display:none!important}
#game{position:absolute;inset:0;width:100%;height:100%}
#hud{position:absolute;inset:0;pointer-events:none;z-index:5}
#topbar{position:absolute;left:0;right:0;top:0;height:72px;display:flex;justify-content:space-between;
  align-items:center;padding:14px 20px;background:linear-gradient(#030b12cc,transparent)}
.brand{line-height:1;text-shadow:0 2px 18px #000}
.brand .marvel{font-size:9px;font-weight:900;letter-spacing:.42em;color:var(--cyan);display:block;margin-bottom:5px}
.brand .name{font-size:21px;font-weight:900;letter-spacing:.09em}
.brand .name em{font-style:normal;color:var(--cyan)}
.stats{display:flex;align-items:center;gap:8px;pointer-events:auto}
.stat{height:38px;display:flex;align-items:center;gap:8px;padding:0 12px;border:1px solid var(--line);
  background:var(--panel);backdrop-filter:blur(12px);border-radius:6px;font-size:12px;letter-spacing:.04em}
.stat svg{opacity:.8}
.stat b{color:var(--gold);font-size:12px}
.iconbtn{width:40px;height:40px;border:1px solid var(--line);background:var(--panel);color:var(--white);
  border-radius:6px;cursor:pointer;font-size:16px;pointer-events:auto;backdrop-filter:blur(12px)}
.iconbtn:active{transform:scale(.95)}
#questPanel{position:absolute;left:20px;top:86px;width:236px;padding:13px 14px;background:var(--panel);
  border:1px solid var(--line);border-left:2px solid var(--cyan);border-radius:4px;backdrop-filter:blur(12px)}
.kicker{font-size:8px;font-weight:900;letter-spacing:.24em;color:var(--cyan)}
#questTitle{font-size:13px;font-weight:800;margin:7px 0 4px;letter-spacing:.02em}
#questDesc{font-size:10.5px;line-height:1.55;color:#a9bdc5}
#questDist{font-size:9px;color:var(--gold);margin-top:8px;letter-spacing:.08em}
#vitals{position:absolute;left:20px;bottom:20px;width:238px;padding:12px 14px;background:var(--panel);
  border:1px solid var(--line);border-radius:6px;backdrop-filter:blur(12px)}
.vitalsTop{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:8px}
.vitalsTop span{font-size:9px;letter-spacing:.12em;color:var(--soft)}
.vitalsTop b{font-size:12px;color:var(--gold)}
.vline{display:flex;align-items:center;gap:8px;margin-top:5px}
.vline label{width:9px;font-size:7px;font-weight:900;color:#7d929b}
.track{flex:1;height:5px;background:#13252d;border-radius:6px;overflow:hidden}
.track i{display:block;height:100%;width:100%;transition:width .18s}
#hpFill{background:linear-gradient(90deg,#ff5e58,#ff9c68)}
#stFill{background:linear-gradient(90deg,#46c5a1,#8ce8c5)}
#xpFill{background:var(--cyan)}
#minimapWrap{position:absolute;right:20px;top:86px;width:176px;border:1px solid var(--line);
  background:var(--panel);border-radius:4px;overflow:hidden;pointer-events:auto;cursor:pointer;backdrop-filter:blur(12px)}
#minimapWrap .mmHead{height:22px;display:flex;align-items:center;justify-content:space-between;
  padding:0 8px;font-size:7.5px;letter-spacing:.18em;color:var(--cyan);border-bottom:1px solid #17313b}
#minimap{width:100%;height:132px;display:block}
#prompt{position:absolute;left:50%;bottom:26px;transform:translateX(-50%);height:38px;padding:0 16px;
  display:flex;align-items:center;gap:9px;background:rgba(4,14,20,.93);border:1px solid var(--gold);
  border-radius:5px;font-size:11px;letter-spacing:.06em;opacity:0;transition:opacity .16s;white-space:nowrap}
#prompt.show{opacity:1}
#prompt kbd{background:var(--gold);color:#191307;border-radius:3px;padding:2px 6px;font:900 9px/1.4 monospace}
#toasts{position:absolute;top:82px;left:50%;transform:translateX(-50%);display:flex;flex-direction:column;
  gap:6px;align-items:center;z-index:20;width:min(360px,86vw)}
.toast{background:rgba(4,16,22,.95);border:1px solid var(--line);border-left:2px solid var(--gold);
  padding:9px 13px;font-size:11px;line-height:1.4;border-radius:3px;animation:toastIn .3s ease both;text-align:center}
@keyframes toastIn{from{opacity:0;transform:translateY(-8px)}to{opacity:1;transform:none}}
#dialogue{position:absolute;z-index:12;left:50%;bottom:38px;transform:translateX(-50%);
  width:min(640px,calc(100% - 32px));background:rgba(4,13,18,.97);border:1px solid rgba(116,228,255,.4);
  border-radius:8px;padding:16px 18px 15px;box-shadow:0 18px 60px #000;pointer-events:auto}
.dlgTop{display:flex;align-items:center;gap:10px;margin-bottom:8px}
#speakerBadge{width:34px;height:34px;border-radius:50%;border:1px solid var(--cyan);display:grid;
  place-items:center;font-size:10px;font-weight:900;color:var(--cyan);background:#0b2a35}
#speaker{font-size:9px;font-weight:900;letter-spacing:.2em;color:var(--cyan)}
#dialogText{font-size:13.5px;line-height:1.62;margin:0 0 13px;color:#e3f4f8}
#choices{display:flex;gap:8px;flex-wrap:wrap}
.choice{border:1px solid #34505c;background:#0c202a;color:var(--white);border-radius:4px;
  padding:9px 13px;font-size:11px;cursor:pointer;text-align:left}
.choice:hover,.choice:focus{border-color:var(--cyan);background:#123440;outline:none}
.choice small{display:block;color:var(--gold);font-size:8px;margin-top:3px}
#modal{position:fixed;inset:0;z-index:30;display:flex;align-items:center;justify-content:center;
  background:rgba(1,5,8,.72);backdrop-filter:blur(6px);padding:18px}
.mpanel{width:min(760px,100%);max-height:min(720px,92vh);background:#06131a;border:1px solid rgba(116,228,255,.3);
  border-radius:8px;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 30px 100px #000}
.mhead{height:56px;display:flex;align-items:center;justify-content:space-between;padding:0 18px;
  border-bottom:1px solid #16313b}
.mhead b{font-size:12px;letter-spacing:.2em;color:var(--cyan)}
.mclose{width:32px;height:32px;border:1px solid #2a4650;background:transparent;color:#bfd4dc;
  border-radius:4px;cursor:pointer}
.tabs{display:flex;border-bottom:1px solid #16313b;overflow-x:auto}
.tab{flex:1;min-width:84px;height:42px;border:0;border-bottom:2px solid transparent;background:transparent;
  color:#8ea4ad;font-size:10px;font-weight:800;letter-spacing:.12em;cursor:pointer}
.tab.active{color:var(--white);border-bottom-color:var(--cyan);background:rgba(116,228,255,.04)}
#modalBody{padding:18px;overflow:auto;min-height:300px}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.card{border:1px solid #1c3944;border-radius:5px;padding:12px;background:#081a22}
.card h4{margin:0 0 6px;font-size:11px;letter-spacing:.1em;color:var(--cyan)}
.card p,.card li{font-size:11px;line-height:1.6;color:#a9bec7;margin:0}
.card ul{padding-left:15px;margin:4px 0}
.bigNum{font-size:26px;font-weight:900;color:var(--white);letter-spacing:.02em}
.pillRow{display:flex;gap:6px;flex-wrap:wrap;margin-top:8px}
.pill{border:1px solid #294854;border-radius:20px;padding:4px 9px;font-size:9px;color:#b7cdd5}
.barLg{height:6px;background:#142b34;border-radius:6px;overflow:hidden;margin:8px 0 4px}
.barLg i{display:block;height:100%;background:linear-gradient(90deg,var(--cyan),#4aa8cd)}
.listRow{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:9px 0;
  border-bottom:1px solid #142a33;font-size:11px;color:#b5c8d0}
.listRow b{color:var(--white);font-size:11px}
.small{font-size:9px;color:#7f959e;line-height:1.5}
.btn{border:1px solid var(--cyan);background:rgba(116,228,255,.08);color:var(--white);padding:8px 12px;
  border-radius:4px;font-size:10px;font-weight:800;letter-spacing:.08em;cursor:pointer}
.btn.gold{border-color:var(--gold);background:rgba(255,207,92,.08)}
.btn.danger{border-color:#ff6d66;background:rgba(255,109,102,.06);color:#ffb6b2}
.btn:disabled{opacity:.35;cursor:not-allowed}
#mapCanvas{width:100%;height:min(440px,52vh);display:block;background:#071016;border:1px solid #1b3742;border-radius:4px}
.legend{display:flex;gap:14px;flex-wrap:wrap;margin-top:10px;font-size:9px;color:#9fb5be}
.legend i{display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:5px}
#touch{position:absolute;inset:0;z-index:9;pointer-events:none}
#joy{position:absolute;left:20px;bottom:22px;width:104px;height:104px;border-radius:50%;
  border:1px solid rgba(160,210,225,.22);background:rgba(6,18,24,.38);pointer-events:auto;touch-action:none}
#knob{position:absolute;left:31px;top:31px;width:42px;height:42px;border-radius:50%;
  background:rgba(116,228,255,.24);border:1px solid rgba(116,228,255,.65);box-shadow:0 0 18px #74e4ff33}
#touchBtns{position:absolute;right:18px;bottom:26px;display:flex;gap:10px;align-items:flex-end;pointer-events:auto}
.tbtn{width:64px;height:64px;border-radius:50%;border:1px solid rgba(116,228,255,.4);
  background:rgba(6,20,27,.78);color:var(--white);font-size:9px;font-weight:900;letter-spacing:.08em;
  display:grid;place-items:center;touch-action:none;backdrop-filter:blur(8px)}
.tbtn.attack{width:76px;height:76px;border-color:rgba(255,207,92,.55);color:var(--gold)}
.tbtn:active{transform:scale(.94);background:rgba(116,228,255,.16)}
#startScreen{position:absolute;inset:0;z-index:40;display:flex;flex-direction:column;
  background:radial-gradient(ellipse at 72% 35%,rgba(10,43,58,.4),transparent 55%),
  linear-gradient(90deg,#02070b 0%,rgba(2,7,11,.94) 42%,rgba(2,7,11,.2) 75%,rgba(2,7,11,.55) 100%)}
.stWrap{width:min(1180px,94%);margin:auto;display:flex;align-items:center;gap:38px;padding:22px 0}
.stLeft{width:min(510px,100%)}
.eyebrow{font-size:9px;font-weight:900;letter-spacing:.46em;color:var(--cyan);margin-bottom:14px}
h1{margin:0;font-size:clamp(44px,7vw,80px);line-height:.86;letter-spacing:.02em;font-weight:900}
h1 span{color:var(--cyan);display:block}
.tagline{font-size:11px;letter-spacing:.22em;color:#8fa6b0;margin:16px 0 22px}
.hook{font-size:12.5px;line-height:1.7;color:#b8ccd4;max-width:430px;margin:0 0 20px}
.fieldLabel{font-size:8px;font-weight:900;letter-spacing:.22em;color:var(--cyan);margin-bottom:6px}
#heroName{width:100%;height:38px;background:#071820;border:1px solid #24434f;border-radius:4px;
  color:var(--white);padding:0 11px;font-size:12px;outline:none;letter-spacing:.04em}
#heroName:focus{border-color:var(--cyan)}
.origins{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin:10px 0 16px}
.origin{border:1px solid #1c3944;background:#06141b;border-radius:5px;padding:10px 9px;cursor:pointer;
  text-align:left;color:#b9cbd2;transition:.16s}
.origin b{display:block;font-size:9.5px;color:var(--white);letter-spacing:.03em;margin-bottom:4px}
.origin small{display:block;font-size:8.5px;line-height:1.45;color:#8298a1}
.origin.sel{border-color:var(--gold);background:rgba(255,207,92,.08);box-shadow:inset 0 0 0 1px rgba(255,207,92,.15)}
.origin.sel b{color:var(--gold)}
.primaryBtn{width:100%;height:46px;border:1px solid var(--cyan);border-radius:4px;cursor:pointer;
  background:linear-gradient(90deg,rgba(116,228,255,.2),rgba(116,228,255,.05));color:#fff;
  font-size:11px;font-weight:900;letter-spacing:.22em}
.primaryBtn:hover{background:rgba(116,228,255,.24)}
.ghostBtn{width:100%;height:34px;margin-top:7px;border:1px solid transparent;background:transparent;
  color:#8da4ad;font-size:9px;letter-spacing:.16em;cursor:pointer}
.ghostBtn:hover{color:var(--white)}
.stRight{flex:1;display:flex;flex-direction:column;align-items:flex-end;gap:20px}
#planetPreview{width:min(440px,36vw);aspect-ratio:1;border-radius:50%;position:relative;
  background:radial-gradient(circle at 34% 30%,#a9e9ef 0,#2c9bb1 22%,#0a516b 58%,#041018 100%);
  box-shadow:0 0 90px rgba(64,185,220,.28),inset -28px -16px 60px #000;
  animation:float 7s ease-in-out infinite}
#planetPreview:before{content:"";position:absolute;inset:0;border-radius:50%;
  background:radial-gradient(circle at 68% 72%,transparent 40%,rgba(0,0,0,.6) 75%);
  box-shadow:inset -24px -14px 60px rgba(0,0,0,.8)}
#planetPreview:after{content:"";position:absolute;inset:-9px;border-radius:50%;
  border:1px solid rgba(116,228,255,.22);box-shadow:0 0 50px rgba(116,228,255,.12)}
@keyframes float{0%,100%{transform:translateY(-6px)}50%{transform:translateY(8px)}}
.stRight .caption{font-size:8px;letter-spacing:.28em;color:#7d949e;text-align:right;line-height:1.9}
.stations{display:flex;gap:18px;font-size:8px;letter-spacing:.14em;color:#78909a;margin-top:4px}
.stations b{color:var(--cyan);display:block;font-size:11px;letter-spacing:.04em;margin-bottom:3px}
#planetPanel{position:absolute;left:0;right:0;bottom:0;z-index:6;padding:0 0 34px;
  display:flex;justify-content:center;pointer-events:none;
  background:linear-gradient(transparent,rgba(1,5,8,.72))}
.pCard{pointer-events:auto;width:min(470px,calc(100% - 36px));text-align:center;padding:16px 18px 15px;
  background:rgba(3,12,17,.78);border:1px solid rgba(116,228,255,.25);border-radius:6px;backdrop-filter:blur(10px)}
#pKicker{font-size:8px;letter-spacing:.3em;color:var(--cyan);margin-bottom:4px}
#pName{font-size:29px;font-weight:900;letter-spacing:.01em;line-height:1.1}
#pMeta{font-size:9px;letter-spacing:.18em;color:#93abb5;margin-top:5px}
#pDesc{font-size:10px;line-height:1.5;color:#8da4ad;margin:9px auto 12px;max-width:360px}
#pEnter{height:40px;width:100%;border:1px solid var(--cyan);border-radius:4px;background:rgba(116,228,255,.09);
  color:var(--white);font-size:10px;font-weight:900;letter-spacing:.16em;cursor:pointer}
#pEnter:disabled{border-color:#2c424b;color:#657b84;cursor:not-allowed;background:transparent}
#planetHint{position:absolute;right:22px;bottom:26px;z-index:6;text-align:right;font-size:8px;
  letter-spacing:.16em;color:#708890;line-height:2;pointer-events:none}
#uranium{position:absolute;top:86px;left:20px;z-index:6;font-size:8px;letter-spacing:.24em;color:#6b838d}
#flash{position:fixed;inset:0;background:#d9f7ff;opacity:0;pointer-events:none;z-index:50;transition:opacity .35s}
#flash.on{opacity:1}
@media(max-width:820px){
  #topbar{height:60px;padding:10px 12px}
  .brand .name{font-size:16px}.brand .marvel{font-size:7px}
  .stat{height:32px;padding:0 8px;font-size:10px;gap:5px}
  .stat.credits{display:none}
