      { label: 'Aceptar $120.', note: '+120 créditos · +70 XP', action: () => { state.jessica = 3; state.credits += 120; addXp(70); notify('Misión completada: Las desaparecidas. +$120', 'good'); saveGame(); } }
    ]);
  } else {
