253: /* ------------- touch controls ------------- */
254: const joyEl = $('#joy'), knob = $('#knob');
255: let joyId = null;
256: function joyStart(e) {
257:   e.preventDefault();
258:   joyId = e.pointerId;
259:   joyEl.setPointerCapture(e.pointerId);
260:   joyMove(e);
261: }
262: function joyMove(e) {
263:   if (e.pointerId !== joyId) return;
264:   const r = joyEl.getBoundingClientRect();
265:   let x = e.clientX - (r.left + r.width / 2);
266:   let y = e.clientY - (r.top + r.height / 2);
267:   const max = r.width * .31;
268:   const len = Math.hypot(x, y);
269:   if (len > max) { x = x / len * max; y = y / len * max; }
270:   knob.style.transform = `translate(${x}px,${y}px)`;
271:   joy.dx = x / max; joy.dy = y / max; joy.active = true;
272: }
273: function joyEnd(e) {
274:   if (e && e.pointerId !== joyId) return;
275:   joyId = null; joy.dx = 0; joy.dy = 0; joy.active = false;
276:   knob.style.transform = '';
277: }
278: joyEl.addEventListener('pointerdown', joyStart);
279: joyEl.addEventListener('pointermove', joyMove);
280: joyEl.addEventListener('pointerup', joyEnd);
